    correction: [{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">18 = 3 × 6</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">27 = 3 × 9</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">18n + 27 = 3(6n + 9)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">3 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"}],
