    correction: [{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 14 و هو زوجي، و 35 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">14 = 7 × 2</span> و <span dir=\"ltr\" class=\"expr\">35 = 7 × 5</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 7 يقسم 14 و يقسم 35"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 7 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"}],
