    correction: [{"quoi":"شرط الباقي","math":"الباقي في القسمة على 6 يجب أن يكون أصغر تماما من 6"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">9 &gt; 6</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 9 لا يمكن أن يكون باقي قسمة على 6"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">9 = 6 × 1 + 3</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">24y + 9 = 6(4y + 1) + 3</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 3 لأنّ 3 < 6"},{"quoi":"الجواب","math":"خطأ"}],
