    correction: [{"quoi":"نفكّك العبارة الأولى","math":"<span dir=\"ltr\" class=\"expr\">28n + 14 = 7(4n + 2)</span>"},{"quoi":"نفكّك العبارة الثانية","math":"<span dir=\"ltr\" class=\"expr\">7n + 7 = 7(1n + 1)</span>"},{"quoi":"نستنتج قاسما مشتركا","math":"العدد 7 يقسم العبارتين مهما يكن n"},{"quoi":"نقارن بالتعريف","math":"عددان أوليان فيما بينهما ق.م.أ لهما يساوي 1، و هنا ق.م.أ يقبل القسمة على 7"},{"quoi":"الجواب","math":"خطأ"}],
