    correction: [{"quoi":"شرط الباقي","math":"الباقي في القسمة على 5 يجب أن يكون أصغر تماما من 5"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">7 &gt; 5</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 7 لا يمكن أن يكون باقي قسمة على 5"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">7 = 5 × 1 + 2</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">20y + 7 = 5(4y + 1) + 2</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 2 لأنّ 2 < 5"},{"quoi":"الجواب","math":"خطأ"}],
