    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">9<sup>745</sup> = 3<sup>1490</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>1490</sup> + n × 3<sup>1487</sup> = 3<sup>1487</sup>(3<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">12 = 3 × 4</span>"},{"quoi":"العامل 3 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">3<sup>1487</sup> = 3 × 3<sup>1486</sup></span>"},{"quoi":"يبقى الشرط على 4","math":"بما أنّ 4 و 3 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">3<sup>3</sup> + n</span> القسمة على 4"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">3<sup>3</sup> = 27</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 30 بحيث يقبل <span dir=\"ltr\" class=\"expr\">27 + n</span> القسمة على 4"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 5 ؛ 9 ؛ 13 ؛ 17 ؛ 21 ؛ 25 ؛ 29</span>"}],
